import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import Link from 'next/link'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { fetchStudioPortfolio } from '@/lib/portfolio/portfolio'
import { listStyleTags } from '@/lib/style-tags/style-tags'
import { createClient } from '@/lib/supabase/server'
import { StudioPortfolioGallery } from '@/components/portfolio/StudioPortfolioGallery'
import { Skeleton } from '@/components/ui/skeleton'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { Button } from '@/components/ui/button'

export const metadata: Metadata = {
  title: 'Flash & Portfolio — InkOS',
}

async function PortfolioContent() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()
  const { data: artists } = await supabase
    .from('artists')
    .select('id, display_name, avatar_url')
    .eq('studio_id', auth.studioId)
    .eq('status', 'active')
    .order('sort_order', { ascending: true })

  const [items, styleTags] = await Promise.all([
    fetchStudioPortfolio(auth.studioId).catch(() => []),
    listStyleTags(auth.studioId).catch(() => []),
  ])

  return (
    <StudioPortfolioGallery
      items={items}
      styleTags={styleTags}
      artists={artists ?? []}
      canManage={['owner', 'admin'].includes(auth.role)}
    />
  )
}

function PortfolioSkeleton() {
  return (
    <div className="p-6 space-y-6">
      <Skeleton className="h-8 w-48" />
      <div className="flex gap-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-8 w-20 rounded-full" />
        ))}
      </div>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
        {Array.from({ length: 12 }).map((_, i) => (
          <Skeleton key={i} className="aspect-square rounded-xl" />
        ))}
      </div>
    </div>
  )
}

export default function PortfolioPage() {
  return (
    <PageShell>
      <PageHeader
        title="Flash & Portfolio"
        description="Studio portfolio gallery"
        actions={
          <Button variant="outline" size="sm" render={<Link href="/artists" />}>
            Manage artists
          </Button>
        }
      />
      <Suspense fallback={<PortfolioSkeleton />}>
        <PortfolioContent />
      </Suspense>
    </PageShell>
  )
}
